import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from 'react-leaflet';
import L from 'leaflet';
import VehicleIcon from './VehicleIcon';
import StationIcon from './StationIcon';
import io from 'socket.io-client';
import 'leaflet.marker.slideto';

const socket = io('http://127.0.0.1:5000');

const MapClickHandler = ({ onMapClick }) => {
  useMapEvents({
    click: (e) => {
      if (e && e.latlng) {
        const { lat, lng } = e.latlng;
        onMapClick({ lat, lng });
      } else {
        console.error("LatLng is undefined", e);
      }
    },
  });
  return null;
};

const getOffset = (index) => {
  const offset = 0.0002; // Adjust this value for better spacing
  return {
    lat: (index % 10) * offset,
    lng: Math.floor(index / 10) * offset
  };
};

const MapComponent = React.memo(({ vehicles, stations, vehicleLocations, onMapClick }) => {
  const [currentPositionIndex, setCurrentPositionIndex] = useState(0);
  const [positions, setPositions] = useState(vehicleLocations);

  useEffect(() => {
    if (vehicleLocations.length > 0) {
      const interval = setInterval(() => {
        setCurrentPositionIndex((prevIndex) => {
          const newIndex = (prevIndex + 1) % vehicleLocations.length;
          return newIndex;
        });
      }, 1000); // change position every second

      return () => clearInterval(interval);
    }
  }, [vehicleLocations]);

  useEffect(() => {
    if (positions.length > 0) {
      // Update the positions of vehicles
      setPositions((prevPositions) => {
        const updatedPositions = [...prevPositions];
        updatedPositions[currentPositionIndex] = vehicleLocations[currentPositionIndex];
        return updatedPositions;
      });
    }
  }, [currentPositionIndex, vehicleLocations]);

  return (
    <MapContainer center={[-37.814, 144.96332]} zoom={13} style={{ height: '100%', width: '100%' }}>
      <TileLayer
        url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        attribution="&copy; <a href='https://www.openstreetmap.org/copyright'>OpenStreetMap</a> contributors"
      />
      <MapClickHandler onMapClick={onMapClick} />
      {vehicles.map((vehicle, index) => {
        const offset = getOffset(index);
        const position = [
          vehicle.location.lat + offset.lat,
          vehicle.location.lng + offset.lng
        ];

        return (
          <Marker key={vehicle.id} position={position} icon={VehicleIcon}>
            <Popup>
              <div>
                <h3>{vehicle.name}</h3>
                <p>Capacity: {vehicle.battery_capacity}</p>
                <p>Battery: {vehicle.battery}</p>
                <p>Consumption: {vehicle.consumption}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
      {stations.map((station, index) => {
        const offset = getOffset(index + vehicles.length);
        const position = [
          station.location.lat + offset.lat,
          station.location.lng + offset.lng
        ];

        return (
          <Marker key={station.id} position={position} icon={StationIcon}>
            <Popup>
              <div>
                <h3>{station.name}</h3>
                <p>Price per kwh: {station.price_per_kwh}</p>
                <p>Charging speed: {station.charging_speed}</p>
                <p>Buy price per kwh: {station.buy_price_per_kwh}</p>
                <p>Discharging speed: {station.discharging_speed}</p>
              </div>
            </Popup>
          </Marker>
        );
      })}
    </MapContainer>
  );
});

export default MapComponent;
